  const gridLines = useMemo(() => {
    const lines: { x1: number; y1: number; x2: number; y2: number }[] = [];
    for (let x = 0; x <= W; x += 60) lines.push({ x1: x, y1: 0, x2: x, y2: H });
    for (let y = 0; y <= H; y += 42) lines.push({ x1: 0, y1: y, x2: W, y2: y });
    return lines;
